
#include "archive_service.h"

#include "compression.h"
#include "file_utils.h"

#include <filesystem>
#include <iostream>
#include <system_error>

namespace fs = std::filesystem;

static fs::path getMetadataPath(
    const std::string& archiveRoot,
    const std::string& archiveId
) {
    return fs::path(archiveRoot) /
           "metadata" /
           (archiveId + ".meta");
}

// Remove only the specific artifact generated by this operation.
// fs::remove does not recursively delete directories.
static bool removeGeneratedPath(
    const fs::path& path,
    const char* description
) {
    if (path.empty()) {
        return true;
    }

    std::error_code error;
    fs::remove(path, error);

    if (error) {
        std::cerr
            << "Archive cleanup warning: could not remove "
            << description << " '"
            << path.string() << "': "
            << error.message() << '\n';

        return false;
    }

    return true;
}


static bool cleanupArchiveArtifacts(
    const std::string& archiveRoot,
    const ArchiveMetadata& metadata
) {
    // Remove the compressed archive first. If removal fails,
    // preserve its metadata so the remaining artifact is visible
    // and can be recovered instead of becoming an orphan.
    if (!metadata.archivePath.empty()) {
        if (!removeGeneratedPath(
                fs::path(metadata.archivePath),
                "compressed archive")) {
            std::cerr
                << "Archive metadata retained because the "
                << "compressed archive could not be removed.\n";
            return false;
        }
    }

    // Remove metadata only after the archive is confirmed absent.
    if (!metadata.archiveId.empty()) {
        if (!removeGeneratedPath(
                getMetadataPath(
                    archiveRoot,
                    metadata.archiveId
                ),
                "archive metadata")) {
            return false;
        }
    }

    return true;
}

// Remove the verification directory only when this operation
// created it. Never recursively remove a user-owned directory.
static void cleanupCreatedVerifyFolder(
    const fs::path& verifyFolder,
    bool verifyFolderCreated
) {
    if (verifyFolderCreated) {
        removeGeneratedPath(
            verifyFolder,
            "newly created verification directory"
        );
    }
}

bool archiveAndRemoveOriginal(
    const std::string& filePath,
    const std::string& archiveRoot,
    ArchiveMetadata& metadata
) {
    // Prevent stale metadata from a previous call from being
    // mistaken for artifacts created by this operation.
    metadata = ArchiveMetadata{};

    std::error_code error;

    if (!fs::is_regular_file(
            fs::path(filePath),
            error
        ) || error) {
        return false;
    }

    // Create the compressed archive and its metadata.
    if (!createArchive(
            filePath,
            archiveRoot,
            metadata
        )) {
        // Clean up any artifacts identifiable from a partial
        // archive-creation attempt. The original stays untouched.
        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    const fs::path verifyFolder =
        fs::path(archiveRoot) / "verify";

    error.clear();

    // The return value tells us whether this operation created
    // the directory. A pre-existing directory must be preserved.
    const bool verifyFolderCreated =
        fs::create_directories(
            verifyFolder,
            error
        );

    if (error) {
        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    const fs::path originalName =
        fs::path(metadata.originalName).filename();

    if (metadata.archiveId.empty() ||
        metadata.archivePath.empty() ||
        originalName.empty()) {
        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );
        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    const fs::path verifyPath =
        verifyFolder /
        (
            metadata.archiveId + "_" +
            originalName.string()
        );

    // Never overwrite an existing file at the verification path.
    error.clear();

    const bool verifyPathExists =
        fs::exists(verifyPath, error);

    if (error || verifyPathExists) {
        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );
        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    // Decompress the new archive into a temporary verification file.
    if (!decompressFile(
            metadata.archivePath,
            verifyPath.string(),
            metadata.originalSize
        )) {
        removeGeneratedPath(
            verifyPath,
            "partial verification output"
        );

        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );

        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    // Verify the complete file contents, not just the file size.
    const bool filesAreSame =
        !filesAreDifferent(
            filePath,
            verifyPath.string()
        );

    // The verification output must be removed before the original
    // can be removed. If cleanup fails, preserve the original.
    if (!removeGeneratedPath(
            verifyPath,
            "verification output")) {
        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );

        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    if (!filesAreSame) {
        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );

        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    // The archive has been decompressed and byte-compared against
    // the original. Only now is original-file removal permitted.
    error.clear();

    const bool removed =
        fs::remove(
            fs::path(filePath),
            error
        );

    if (!removed || error) {
        if (error) {
            std::cerr
                << "Original file removal failed: "
                << error.message() << '\n';
        }

        cleanupCreatedVerifyFolder(
            verifyFolder,
            verifyFolderCreated
        );

        cleanupArchiveArtifacts(archiveRoot, metadata);
        return false;
    }

    // Preserve a pre-existing verification directory. If this
    // operation created it, remove it only if it is now empty.
    cleanupCreatedVerifyFolder(
        verifyFolder,
        verifyFolderCreated
    );

    // Successful archive and metadata are retained.
    return true;
}
